    n = len(palette)
    out = [row[:] for row in grid]
    # Every row is a cyclic left-to-right color run. Existing cells anchor
    # its phase; the diagonal duplicate markers are retained, not normalized.
    for r, row in enumerate(grid):
        anchors = [(c, palette.index(v)) for c, v in enumerate(row) if v != 0]
        # Determine the phase that best matches all known cells under +1/col;
        # anomalies are retained in the output but do not control blank fills.
        scores = []
        for phase in range(n):
            scores.append(sum(1 for c, k in anchors if (phase + c) % n == k))
        phase = max(range(n), key=lambda p: scores[p])
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = palette[(phase + c) % n]
    return out
