    # Reconstruct the underlying grid from the undamaged cyclic row/column
    # sequences. The background is row-wise: row r starts at 2 for r=0, then
    # 3 for all later rows, with palette cycling 1..9; damaged zeros cover it.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        start = 2 if r == 0 else 3
        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = ((start - 1 + c) % 9) + 1
    return out
